<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\UserPersonalApiKey\Domain\ValueObject\Accessor\UserPersonalApiKeyLastUsedAtAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the UserPersonalApiKeyLastUsedAtAccessor trait.
 *
 * Covers null default, string/VO assignment via withLastUsedAt,
 * getLastUsedAt/lastUsedAt accessors, and isLastUsedAtChanged with/without original.
 */
class UserPersonalApiKeyLastUsedAtAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withLastUsedAt creates a new instance with the LastUsedAt set
     * from a string value, and getLastUsedAt returns the primitive string.
     */
    public function testWithLastUsedAtFromString(): void
    {
        // Arrange
        $holder = new ImplWithUserPersonalApiKeyLastUsedAtAccessorUnitTest();

        // Act
        $result = $holder->withLastUsedAt((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')));

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')), $result->getLastUsedAt());
    }
    /**
     * Asserts that withlastUsedAt has access to the value object
     * from a string value, and getLastUsedAt returns the primitive string.
     */
    public function testWithLastUsedAtFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithUserPersonalApiKeyLastUsedAtAccessorUnitTest();

        // Act
        $result = $holder->withLastUsedAt((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')));

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')), $result->lastUsedAt()->value());
    }
    public function testChangedLastUsedAt(): void
    {
        // Arrange
        $holder = new ImplWithUserPersonalApiKeyLastUsedAtAccessorUnitTest();
        $original = $holder->withLastUsedAt((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')));
        $same = $holder->withLastUsedAt((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')));
        $modified = $holder->withLastUsedAt((new \DateTimeImmutable('1981-09-06T14:32:45.123Z')));

        // Act
        $unchanged = $holder->isLastUsedAtChanged();
        $withSame = $original->isLastUsedAtChanged($same);
        $withDiferent = $original->isLastUsedAtChanged($modified);

        // Assert
        $this->assertFalse($unchanged);
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithUserPersonalApiKeyLastUsedAtAccessorUnitTest
{
    use UserPersonalApiKeyLastUsedAtAccessor;
}
